            if (photometric == PHOTOMETRIC_MINISWHITE) {
                curr = ~curr;
            }
            for (mask = 0x80; mask != 0 && x < startx + width; mask >>= 1) {
                gdImageSetPixel(im, x, y, ((curr & mask) != 0)?0:1);
            }
        }
    }
}

